   215  static gboolean
   216  fu_coswid_firmware_parse_hash(FuCoswidFirmware *self,
   217                        cbor_item_t *item,
   218                        gpointer user_data,
   219                        GError **error)
   220  {
   221       FuCoswidFirmwarePayload *payload = (FuCoswidFirmwarePayload *)user_data;
   222       g_autoptr(FuCoswidFirmwareHash) hash = g_new0(FuCoswidFirmwareHash, 1);
   223       g_autoptr(cbor_item_t) hash_item_alg_id = cbor_array_get(item, 0);
   224       g_autoptr(cbor_item_t) hash_item_value = cbor_array_get(item, 1);
   225
   226       /* sanity check */
   227       if (hash_item_alg_id == NULL || hash_item_value == NULL) {
   228          g_set_error_literal(error,
   229                              FWUPD_ERROR,
   230                              FWUPD_ERROR_INVALID_DATA,
   231                              "invalid hash item");
   232          return FALSE;
   233       }
   234
   235       /* success */
   236       hash->alg_id = cbor_get_uint8(hash_item_alg_id);
   237       hash->value = g_byte_array_new();
   238       g_byte_array_append(hash->value,
   239                      cbor_bytestring_handle(hash_item_value),
   240                      cbor_bytestring_length(hash_item_value));
   241       g_ptr_array_add(payload->hashes, g_steal_pointer(&hash));
   242       return TRUE;
   243  }
