   411       guint entity_role_cnt = 0;
   412       g_autoptr(FuCoswidFirmwareEntity) entity = g_new0(FuCoswidFirmwareEntity, 1);
   413
   414       for (gsize i = 0; i < cbor_map_size(item); i++) {
   415          FuCoswidTag tag_id = cbor_get_uint8(pairs[i].key);
