   417                  entity->name = fu_coswid_firmware_strndup(pairs[i].value);
   418          } else if (tag_id == FU_COSWID_TAG_REG_ID) {
   419                  entity->regid = fu_coswid_firmware_strndup(pairs[i].value);
   420          } else if (tag_id == FU_COSWID_TAG_ROLE) {
   421                  if (cbor_isa_uint(pairs[i].value)) {
   422                          FuCoswidEntityRole role = cbor_get_uint8(pairs[i].value);
   423                          entity->roles[entity_role_cnt++] = role;
   424                  }
   425                  for (guint j = 0; j < cbor_array_size(pairs[i].value); j++) {
   426                          g_autoptr(cbor_item_t) value = cbor_array_get(pairs[i].value, j);
